/**
 * SourceViewer — read-only source display with line numbers.
 *
 * - Shows bounded line ranges with clear truncation notice
 * - Displays path, language, and hash for identity verification
 * - Never executes any code from the analyzed repository
 * - Keyboard navigation within the code table
 */

import { useEffect, useState } from 'react'
import { getSource } from '../../services/v1/api'
import type { SourceSlice } from '../../types/v1'

interface Props {
  projectId: string
  snapshotId: string
  fileId: string
  path: string
  language: string
  lineStart?: number
  lineEnd?: number
}

type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ready'; slice: SourceSlice }
  | { status: 'error'; message: string }

export function SourceViewer({
  projectId,
  snapshotId,
  fileId,
  path,
  language,
  lineStart = 1,
  lineEnd,
}: Props) {
  const [state, setState] = useState<State>({ status: 'idle' })

  useEffect(() => {
    setState({ status: 'loading' })
    let cancelled = false

    getSource(projectId, snapshotId, fileId, lineStart, lineEnd)
      .then(slice => {
        if (!cancelled) setState({ status: 'ready', slice })
      })
      .catch(err => {
        if (!cancelled) setState({ status: 'error', message: err instanceof Error ? err.message : 'Failed to load source.' })
      })

    return () => { cancelled = true }
  }, [projectId, snapshotId, fileId, lineStart, lineEnd])

  return (
    <div className="source-viewer">
      <div className="source-viewer__header">
        <span className="source-viewer__path" title={path}>
          {path}
        </span>
        <div className="source-viewer__meta">
          {language && (
            <span className="source-badge">{language}</span>
          )}
          {state.status === 'ready' && (
            <span className="source-badge" title={`SHA-256: ${state.slice.content_hash}`}>
              {state.slice.total_lines} lines
            </span>
          )}
        </div>
      </div>

      <div className="source-viewer__code" tabIndex={0} aria-label={`Source code: ${path}`}>
        {state.status === 'loading' && (
          <div style={{ padding: '24px 16px', color: 'var(--grepo-text-secondary)', fontSize: 12 }}>
            <div className="spinner" style={{ display: 'inline-block', marginRight: 8 }} aria-hidden="true" />
            Loading source…
          </div>
        )}

        {state.status === 'error' && (
          <div className="alert alert--error" style={{ margin: 16 }}>
            {state.message}
          </div>
        )}

        {state.status === 'ready' && (
          <table className="source-table" aria-label={`Source lines ${state.slice.line_start}–${state.slice.line_end}`}>
            <tbody>
              {state.slice.content.split('\n').map((line, idx) => {
                const lineNum = state.slice.line_start + idx
                return (
                  <tr key={lineNum}>
                    <td className="source-table__num" aria-hidden="true">{lineNum}</td>
                    <td className="source-table__line">{escapeHtml(line) || '\u200B'}</td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        )}
      </div>

      {state.status === 'ready' && state.slice.truncated && (
        <div className="source-viewer__truncation" role="status">
          Showing lines {state.slice.line_start}–{state.slice.line_end} of {state.slice.total_lines}.
          {' '}Use line range controls to navigate.
        </div>
      )}
    </div>
  )
}

/** Safely escape HTML characters in source lines.
 *  Repository source is always rendered as escaped text — never innerHTML. */
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

